schemas.schema-01-actors.prisma:
/// User accounts for personal todo management.
///
/// Represents individual authenticated users of the Todo List application.
/// Each user owns their own collection of todos and has access restricted
/// strictly to their account. No profile, roles, or shared/group features
/// exist in this minimal application. Supports secure authentication using a
/// unique email and hashed password. Created and updated timestamps track
/// registration and account changes. No soft deletion or role-based access
/// control is present, in line with privacy and simplicity requirements.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Email address used for account authentication and identifier. Must be
  /// unique across all users. Required for login and password reset flows.
  email String

  /// Hashed password (never plain text). Used for secure authentication only.
  password_hash String

  /// Timestamp when the user account was created (UTC). Used for audit and
  /// business reporting.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last change to this user account (credentials, metadata,
  /// etc.). Allows business auditing and security checks.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_user_sessions todo_user_sessions[]
  todo_todos todo_todos[]

  @@unique([email])
  @@index([created_at, email])
}

/// Session records for authenticated user access.
///
/// Tracks individual login sessions for each user, supporting multi-device
/// or concurrent sign-ins. Stores context information such as IP address,
/// connecting URL, and referrer for audit and security analysis. Each
/// session is linked to a single user and has a clear start (created_at) and
/// optional expiry (expired_at) timestamp. Enables audit trails for user
/// actions and supports secure logout flows. Managed exclusively via
/// authentication flows; not created or deleted independently by users.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the owning user. Links session to user. {@link
  /// todo_users.id}.
  todo_user_id String @db.Uuid

  /// IP address from which the session was created. Used for security audits.
  ip String

  /// Connection URL at login. Useful for logging entry points and UI context
  /// of session.
  href String

  /// Referrer URL provided by the browser or client during login session
  /// creation.
  referrer String

  /// Timestamp when the session was established (UTC). Allows analysis of user
  /// activity and session management.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this session expired or was terminated. Null when session
  /// is active.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, created_at])
}

schemas.schema-02-todos.prisma:
/// Individual todo items owned by a specific user.
///
/// Represents a single unit of personal task management, strictly scoped to
/// one authenticated user per business and privacy requirements. A todo
/// includes a required title, optional description, optional due date,
/// optional priority, and flags for completion status and completion
/// timestamp. Each todo is private, never shared, and uniquely associated
/// via a required foreign key to the owning user (see {@link todo_users}).
///
/// All CRUD operations, status toggling, and per-user filtering are
/// supported directly on this table. Business rule validation (such as
/// duplicate title/date per user) is enforced at the application logic
/// level. Deletion is irreversible (no soft delete). Creation and update
/// metadata support audit and recovery scenarios.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a todo item.
  id String @id @db.Uuid

  /// Owner user ID. References the owning authenticated user. {@link
  /// todo_users.id}.
  user_id String @db.Uuid

  /// Short descriptive title for the todo item. Required per business rules.
  /// Maximum length: 255 characters.
  title String

  /// Optional longer details or notes for the todo. Maximum length: 1000
  /// characters. May be null if no description provided.
  description String?

  /// Optional due date for the todo in ISO 8601 format. Must be a valid date
  /// in the future or null if undated.
  due_date DateTime? @db.Timestamptz

  /// Optional task priority. Valid values: 'low', 'medium', 'high'. May be
  /// null if no priority assigned.
  priority String?

  /// Completion status of the todo. True if completed, false otherwise.
  is_completed Boolean

  /// Timestamp when the todo was marked as completed. Null if incomplete.
  completed_at DateTime? @db.Timestamptz

  /// Datetime the todo item was created (UTC, ISO 8601).
  created_at DateTime @db.Timestamptz

  /// Datetime the todo item was last modified (UTC, ISO 8601).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([user_id, title, due_date])
  @@index([user_id, is_completed])
  @@index([user_id, due_date])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

