import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test a user creating a todo with all optional fields populated: title,
 * description (non-null), due_date (future ISO8601), and priority ('high').
 * Confirms:
 *
 * - Success of creation (no unique constraint violated)
 * - All fields stored, correct types in response
 * - Unique (title, due_date) for this user
 */
export async function test_api_todo_creation_with_all_fields(
  connection: api.IConnection,
) {
  // 1. Register a new user for context isolation
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const joinBody = {
    email,
    password,
    href: "https://e2e.test/register",
    referrer: "https://e2e.test/landing?page=todo",
    ip: null,
  } satisfies ITodoUser.ICreate;
  const userAuth: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: joinBody,
    },
  );
  typia.assert(userAuth);

  // 2. Create a todo with all fields (using unique title and future due date)
  const todoTitle = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 3,
    wordMax: 8,
  });
  const description = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 4,
    wordMax: 15,
  });
  const dueDateObj = new Date(Date.now() + 1000 * 60 * 60 * 24 * 3); // 3 days in future
  const due_date = dueDateObj.toISOString();
  const body = {
    title: todoTitle,
    description,
    due_date,
    priority: "high",
  } satisfies ITodoTodo.ICreate;

  const todo: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    { body },
  );
  typia.assert(todo);

  // 3. Validate response
  TestValidator.equals("title matches input", todo.title, todoTitle);
  TestValidator.equals(
    "description matches input",
    todo.description,
    description,
  );
  TestValidator.equals("due_date matches input", todo.due_date, due_date);
  TestValidator.equals("priority is high", todo.priority, "high");
  TestValidator.equals(
    "is_completed is false by default",
    todo.is_completed,
    false,
  );
  TestValidator.equals("completed_at is null", todo.completed_at, null);
  TestValidator.predicate("created_at is ISO8601 in the past", () => {
    return (
      typeof todo.created_at === "string" &&
      !Number.isNaN(Date.parse(todo.created_at)) &&
      Date.parse(todo.created_at) <= Date.now()
    );
  });
  TestValidator.predicate("updated_at is ISO8601 in the past", () => {
    return (
      typeof todo.updated_at === "string" &&
      !Number.isNaN(Date.parse(todo.updated_at)) &&
      Date.parse(todo.updated_at) <= Date.now()
    );
  });

  // 4. (Business rule) No other todo should share (title, due_date) for this user, and creation worked
  // No duplicate creation attempted, so this tuple should be unique for this account
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Ensures that a user cannot create two todo items with the same title and
 * due_date.
 *
 * 1. Register a new todo user (POST /auth/user/join) to obtain authentication.
 * 2. Create a todo specifying a unique title and due date.
 * 3. Attempt to create another todo with the exact same title and due date (other
 *    fields may differ).
 * 4. Confirm the first create call succeeds with expected persisted data, then
 *    verify the second call triggers uniqueness violation error.
 * 5. Ensure the failed second create does not insert or alter any todo.
 */
export async function test_api_todo_creation_duplicate_title_due_date(
  connection: api.IConnection,
) {
  // 1. Register a new todo user
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const href =
    "https://test-app/autobe-e2e/" + RandomGenerator.alphaNumeric(10);
  const referrer = "https://referrer-site/" + RandomGenerator.alphaNumeric(8);
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password,
      href,
      referrer,
    } satisfies ITodoUser.ICreate,
  });
  typia.assert(user);

  // 2. Prepare duplicate title and due date
  const todoTitle = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 4,
    wordMax: 10,
  });
  const dueDate = new Date(Date.now() + 86400000).toISOString(); // +1 day

  // 3. Create first todo
  const todoInput = {
    title: todoTitle,
    due_date: dueDate,
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 2,
      sentenceMax: 5,
      wordMin: 4,
      wordMax: 8,
    }),
    priority: RandomGenerator.pick(["low", "medium", "high"] as const),
  } satisfies ITodoTodo.ICreate;
  const created = await api.functional.todo.user.todos.create(connection, {
    body: todoInput,
  });
  typia.assert(created);
  TestValidator.equals(
    "created todo item matches input title",
    created.title,
    todoInput.title,
  );
  if (created.due_date !== null && created.due_date !== undefined) {
    TestValidator.equals(
      "created todo item matches due date",
      created.due_date,
      todoInput.due_date,
    );
  }
  TestValidator.equals(
    "created todo item priority matches",
    created.priority,
    todoInput.priority,
  );
  TestValidator.equals(
    "created todo is not completed",
    created.is_completed,
    false,
  );
  TestValidator.predicate(
    "todo id is valid uuid",
    typeof created.id === "string" && created.id.length > 0,
  );

  // 4. Attempt to create duplicate todo (same title + due date)
  await TestValidator.error(
    "cannot create another todo with same title and due date per user",
    async () => {
      await api.functional.todo.user.todos.create(connection, {
        body: todoInput,
      });
    },
  );

  // 5. Confirm state of the originally created todo remains unchanged (no fetch/list API available here for further verification)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test updating a todo's title, description, due date, and priority for an
 * existing todo owned by the user. Validates ownership-based access,
 * persistence of changes, and audit field updates. Only the owner may update,
 * and only requested fields change.
 */
export async function test_api_todo_update_basic_fields(
  connection: api.IConnection,
) {
  // 1. Register a user (owner)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = RandomGenerator.alphaNumeric(10);
  const ownerJoin = await api.functional.auth.user.join(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      href: "https://example.com/join",
      referrer: "https://example.com/landing",
      ip: null,
    } satisfies ITodoUser.ICreate,
  });
  typia.assert(ownerJoin);

  // 2. Create a todo for this user
  const todoCreate = await api.functional.todo.user.todos.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 2,
        wordMin: 3,
        wordMax: 10,
      }),
      description: RandomGenerator.paragraph({
        sentences: 8,
        wordMin: 6,
        wordMax: 15,
      }),
      due_date: new Date(Date.now() + 86400 * 1000 * 5).toISOString(),
      priority: RandomGenerator.pick(["low", "medium", "high"] as const),
    } satisfies ITodoTodo.ICreate,
  });
  typia.assert(todoCreate);

  // 3. Update the todo's title, description, due_date, and priority
  const updatedTitle = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 4,
    wordMax: 10,
  });
  const updatedDescription = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 6,
    wordMax: 20,
  });
  const updatedDueDate = new Date(Date.now() + 86400 * 1000 * 10).toISOString();
  const updatedPriority = RandomGenerator.pick([
    "low",
    "medium",
    "high",
  ] as const);

  const updated = await api.functional.todo.user.todos.update(connection, {
    todoId: todoCreate.id,
    body: {
      title: updatedTitle,
      description: updatedDescription,
      due_date: updatedDueDate,
      priority: updatedPriority,
    } satisfies ITodoTodo.IUpdate,
  });
  typia.assert(updated);

  // 4. Assert updated fields match
  TestValidator.equals("todo title updated", updated.title, updatedTitle);
  TestValidator.equals(
    "todo description updated",
    updated.description,
    updatedDescription,
  );
  TestValidator.equals(
    "todo due_date updated",
    updated.due_date,
    updatedDueDate,
  );
  TestValidator.equals(
    "todo priority updated",
    updated.priority,
    updatedPriority,
  );

  // 5. Confirm audit field 'updated_at' is updated and differs from original
  TestValidator.notEquals(
    "updated_at has changed",
    updated.updated_at,
    todoCreate.updated_at,
  );

  // 6. Register a different user, attempt unauthorized update
  const hackerEmail = typia.random<string & tags.Format<"email">>();
  const hackerPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.user.join(connection, {
    body: {
      email: hackerEmail,
      password: hackerPassword,
      href: "https://example.com/join",
      referrer: "https://example.com/landing",
      ip: null,
    } satisfies ITodoUser.ICreate,
  });

  await TestValidator.error("non-owner cannot update todo", async () => {
    await api.functional.todo.user.todos.update(connection, {
      todoId: todoCreate.id,
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 4,
          wordMax: 10,
        }),
      } satisfies ITodoTodo.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate updating a todo to mark it as completed.
 *
 * Steps:
 *
 * 1. Register and authenticate a new user.
 * 2. Create a new todo (should default to is_completed: false).
 * 3. Update the new todo to set is_completed: true with a valid completed_at
 *    timestamp.
 * 4. Verify that is_completed is true and completed_at is a valid ISO 8601
 *    timestamp in the response.
 * 5. Ensure completed_at is present ONLY when is_completed is true.
 */
export async function test_api_todo_update_mark_as_completed(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new user
  const userCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test.example.com/todos",
    referrer: "https://test.example.com/",
    ip: null,
  } satisfies ITodoUser.ICreate;
  const authUser: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userCreate },
  );
  typia.assert(authUser);
  // 2. Create a new todo (should be incomplete by default)
  const todoCreate = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 10 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // due tomorrow
    priority: RandomGenerator.pick(["low", "medium", "high"] as const),
  } satisfies ITodoTodo.ICreate;
  const created: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    { body: todoCreate },
  );
  typia.assert(created);
  TestValidator.equals(
    "new todo is not completed by default",
    created.is_completed,
    false,
  );
  TestValidator.equals(
    "completed_at is null by default",
    created.completed_at,
    null,
  );
  // 3. Update the todo to mark as completed
  const completedAt = new Date().toISOString();
  const updateReq = {
    is_completed: true,
    completed_at: completedAt,
  } satisfies ITodoTodo.IUpdate;
  const updated: ITodoTodo = await api.functional.todo.user.todos.update(
    connection,
    { todoId: created.id, body: updateReq },
  );
  typia.assert(updated);
  // 4. Check updated fields
  TestValidator.equals("todo marked as completed", updated.is_completed, true);
  TestValidator.equals(
    "completed_at is set when completed",
    updated.completed_at,
    completedAt,
  );
  // 5. Check completed_at is not populated if is_completed is false (revert to incomplete)
  const updateBack = {
    is_completed: false,
    completed_at: null,
  } satisfies ITodoTodo.IUpdate;
  const reverted: ITodoTodo = await api.functional.todo.user.todos.update(
    connection,
    { todoId: created.id, body: updateBack },
  );
  typia.assert(reverted);
  TestValidator.equals("todo uncompleted", reverted.is_completed, false);
  TestValidator.equals(
    "completed_at should be null if not completed",
    reverted.completed_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test that only the owner user may update personal todos, enforcing privacy
 * and business rules.
 *
 * 1. Register User A (first user) and authenticate
 * 2. With User A, create a new todo item (store id and content)
 * 3. Register User B (second user) and authenticate (switch context)
 * 4. User B attempts to update User A's todo item (should fail — forbidden)
 * 5. Assert that update is denied and that the todo content remains as originally
 *    set
 */
export async function test_api_todo_update_ownership_enforcement(
  connection: api.IConnection,
) {
  // 1. Register User A and authenticate
  const userA_email: string = typia.random<string & tags.Format<"email">>();
  const userA_password: string = RandomGenerator.alphaNumeric(12);
  const userA: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userA_email,
        password: userA_password,
        href: "https://test-a.com/signup",
        referrer: "https://google.com",
        ip: null,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(userA);

  // 2. User A creates a todo
  const todoTitleA = RandomGenerator.paragraph({ sentences: 1 });
  const todoDescA = RandomGenerator.paragraph({ sentences: 3 });
  const todoPayload = {
    title: todoTitleA,
    description: todoDescA,
    due_date: null,
    priority: "medium",
  } satisfies ITodoTodo.ICreate;
  const todoA: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    { body: todoPayload },
  );
  typia.assert(todoA);

  // 3. Register User B and authenticate (overwrites connection context)
  const userB_email: string = typia.random<string & tags.Format<"email">>();
  const userB_password: string = RandomGenerator.alphaNumeric(12);
  const userB: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userB_email,
        password: userB_password,
        href: "https://test-b.com/signup",
        referrer: "https://bing.com",
        ip: null,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(userB);

  // 4. User B attempts to update User A's todo (should be forbidden)
  await TestValidator.error(
    "Only owner can update personal todo: User B must not update User A's todo",
    async () => {
      await api.functional.todo.user.todos.update(connection, {
        todoId: todoA.id,
        body: {
          title: todoTitleA + " (hacked)",
        } satisfies ITodoTodo.IUpdate,
      });
    },
  );
}

