import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUserSession";
import { IPageITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoUserActorsMeSessions(props: {
  user: UserPayload;
  body: ITodoUserSession.IRequest;
}): Promise<IPageITodoUserSession> {
  const { page = 1, limit = 20, search, order_by } = props.body ?? {};
  const offset = (page - 1) * limit;
  const where = {
    todo_user_id: props.user.id,
    ...(search && {
      OR: [
        { ip: { contains: search, mode: Prisma.QueryMode.insensitive } },
        { href: { contains: search, mode: Prisma.QueryMode.insensitive } },
        { referrer: { contains: search, mode: Prisma.QueryMode.insensitive } },
      ],
    }),
  };
  const sessions = await MyGlobal.prisma.todo_user_sessions.findMany({
    where,
    orderBy: { [order_by ?? "created_at"]: "desc" },
    skip: offset,
    take: limit,
  });
  const total = await MyGlobal.prisma.todo_user_sessions.count({ where });
  return {
    data: sessions.map((s) => ({
      id: s.id,
      todo_user_id: s.todo_user_id,
      ip: s.ip,
      href: s.href,
      referrer: s.referrer,
      created_at: toISOStringSafe(s.created_at),
      expired_at:
        typeof s.expired_at === "undefined"
          ? undefined
          : s.expired_at
            ? toISOStringSafe(s.expired_at)
            : null,
    })),
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { IPageITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoUserTodos(props: {
  user: UserPayload;
  body: ITodoTodo.IRequest;
}): Promise<IPageITodoTodo.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build where filter for the user's todos
  const where = {
    user_id: props.user.id,
    ...(props.body.is_completed !== undefined && {
      is_completed: props.body.is_completed,
    }),
    ...(props.body.priority !== undefined &&
      props.body.priority !== null && {
        priority: props.body.priority,
      }),
    ...(props.body.due_date_from && {
      due_date: {
        ...(props.body.due_date_from && { gte: props.body.due_date_from }),
        ...(props.body.due_date_to && { lte: props.body.due_date_to }),
      },
    }),
    ...(props.body.due_date_to &&
      !props.body.due_date_from && {
        due_date: { lte: props.body.due_date_to },
      }),
  };

  // Full-text search for title or description
  let searchFilter: object = {};
  if (props.body.search) {
    searchFilter = {
      OR: [
        { title: { contains: props.body.search, mode: "insensitive" } },
        { description: { contains: props.body.search, mode: "insensitive" } },
      ],
    };
  }

  // Compose final where with search
  const finalWhere = {
    ...where,
    ...searchFilter,
  };

  // Sorting logic
  let orderBy: any = { created_at: "desc" };
  if (
    props.body.sort_by &&
    ["created_at", "due_date", "priority"].includes(props.body.sort_by)
  ) {
    orderBy = {
      [props.body.sort_by]: props.body.sort_order === "asc" ? "asc" : "desc",
    };
  }

  const [total, todos] = await Promise.all([
    MyGlobal.prisma.todo_todos.count({ where: finalWhere }),
    MyGlobal.prisma.todo_todos.findMany({
      where: finalWhere,
      orderBy,
      skip,
      take: limit,
      select: {
        id: true,
        user_id: true,
        title: true,
        due_date: true,
        priority: true,
        is_completed: true,
      },
    }),
  ]);

  const data = todos.map((item) => ({
    id: item.id,
    user_id: item.user_id,
    title: item.title,
    due_date: item.due_date ? toISOStringSafe(item.due_date) : undefined,
    priority:
      item.priority !== undefined && item.priority !== null
        ? typia.assert<"low" | "medium" | "high">(item.priority)
        : item.priority,
    is_completed: item.is_completed,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoUserTodos(props: {
  user: UserPayload;
  body: ITodoTodo.ICreate;
}): Promise<ITodoTodo> {
  const now = new Date();
  const nowISOString = toISOStringSafe(now);

  // Check for uniqueness: same user, same title, same due_date (null treated as null)
  const exists = await MyGlobal.prisma.todo_todos.findFirst({
    where: {
      user_id: props.user.id,
      title: props.body.title,
      due_date: props.body.due_date === undefined ? null : props.body.due_date,
    },
  });
  if (exists !== null) {
    throw new HttpException(
      "A todo with the same title and due date already exists.",
      409,
    );
  }

  const created = await MyGlobal.prisma.todo_todos.create({
    data: {
      id: v4(), // Will be returned in correct type below
      user_id: props.user.id,
      title: props.body.title,
      description:
        props.body.description === undefined
          ? undefined
          : props.body.description,
      due_date:
        props.body.due_date === undefined ? undefined : props.body.due_date,
      priority:
        props.body.priority === undefined ? undefined : props.body.priority,
      is_completed: false,
      completed_at: null,
      created_at: nowISOString,
      updated_at: nowISOString,
    },
  });

  return {
    id: created.id,
    user_id: created.user_id,
    title: created.title,
    description: created.description ?? undefined,
    due_date:
      created.due_date !== null && created.due_date !== undefined
        ? toISOStringSafe(created.due_date)
        : created.due_date,
    priority:
      created.priority !== undefined && created.priority !== null
        ? typia.assert<"low" | "medium" | "high">(created.priority)
        : created.priority,
    is_completed: created.is_completed,
    completed_at:
      created.completed_at !== null && created.completed_at !== undefined
        ? toISOStringSafe(created.completed_at)
        : created.completed_at,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoTodo.IUpdate;
}): Promise<ITodoTodo> {
  // Find todo for authenticated user
  const todo = await MyGlobal.prisma.todo_todos.findUnique({
    where: {
      id: props.todoId,
      user_id: props.user.id,
    },
  });
  if (!todo) {
    throw new HttpException("Todo not found", 404);
  }

  // Patch for updating fields (ignore disallowed keys)
  const patch: Record<string, unknown> = {};
  if (Object.prototype.hasOwnProperty.call(props.body, "title"))
    patch.title = props.body.title;
  if (Object.prototype.hasOwnProperty.call(props.body, "description"))
    patch.description =
      props.body.description === undefined ? undefined : props.body.description;
  if (Object.prototype.hasOwnProperty.call(props.body, "due_date"))
    patch.due_date =
      props.body.due_date === undefined ? undefined : props.body.due_date;
  if (Object.prototype.hasOwnProperty.call(props.body, "priority"))
    patch.priority = props.body.priority;
  if (Object.prototype.hasOwnProperty.call(props.body, "is_completed"))
    patch.is_completed = props.body.is_completed;
  if (Object.prototype.hasOwnProperty.call(props.body, "completed_at"))
    patch.completed_at =
      props.body.completed_at === undefined
        ? undefined
        : props.body.completed_at;
  patch.updated_at = toISOStringSafe(new Date());

  // Update. Uniqueness on (user_id, title, due_date) enforced in DB, catch error.
  let updated;
  try {
    updated = await MyGlobal.prisma.todo_todos.update({
      where: { id: props.todoId, user_id: props.user.id },
      data: patch,
    });
  } catch (err) {
    if (
      typeof err === "object" &&
      err !== null &&
      "code" in err &&
      err.code === "P2002"
    ) {
      throw new HttpException(
        "A todo with the same title and due date already exists.",
        409,
      );
    }
    throw err;
  }

  // Format response to ITodoTodo contract (pay careful attention to null vs undefined for optional fields)
  return {
    id: updated.id,
    user_id: updated.user_id,
    title: updated.title,
    description:
      "description" in updated
        ? updated.description === null
          ? null
          : updated.description === undefined
            ? undefined
            : updated.description
        : undefined,
    due_date:
      "due_date" in updated
        ? updated.due_date === null
          ? null
          : updated.due_date === undefined
            ? undefined
            : updated.due_date instanceof Date
              ? toISOStringSafe(updated.due_date)
              : updated.due_date
        : undefined,
    priority:
      "priority" in updated
        ? updated.priority === null
          ? null
          : updated.priority === undefined
            ? undefined
            : typia.assert<"low" | "medium" | "high">(updated.priority)
        : undefined,
    is_completed: updated.is_completed,
    completed_at:
      "completed_at" in updated
        ? updated.completed_at === null
          ? null
          : updated.completed_at === undefined
            ? undefined
            : updated.completed_at instanceof Date
              ? toISOStringSafe(updated.completed_at)
              : updated.completed_at
        : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoUser.IRefresh;
}): Promise<ITodoUser.IAuthorized> {
  let payload: { id: string; session_id: string; type: "user" };
  try {
    payload = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (payload.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  const session = await MyGlobal.prisma.todo_user_sessions.findFirst({
    where: {
      id: payload.session_id,
      todo_user_id: payload.id,
    },
    include: {
      user: true,
    },
  });

  if (!session || !session.user) {
    throw new HttpException("Account not found or deleted", 403);
  }

  const now = Date.now();
  const accessExpires = now + 60 * 60 * 1000;
  const refreshExpires = now + 7 * 24 * 60 * 60 * 1000;

  const accessToken = jwt.sign(
    {
      type: "user",
      id: payload.id,
      session_id: payload.session_id,
      created_at: toISOStringSafe(new Date(now)),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refreshToken = jwt.sign(
    {
      type: "user",
      id: payload.id,
      session_id: payload.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date(now)),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  await MyGlobal.prisma.todo_user_sessions.update({
    where: { id: payload.session_id },
    data: { expired_at: toISOStringSafe(new Date(refreshExpires)) },
  });

  return {
    id: session.user.id,
    email: session.user.email,
    created_at: toISOStringSafe(session.user.created_at),
    updated_at: toISOStringSafe(session.user.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(new Date(accessExpires)),
      refreshable_until: toISOStringSafe(new Date(refreshExpires)),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoUser.ILogin;
}): Promise<ITodoUser.IAuthorized> {
  // 1. Lookup user by email
  const user = await MyGlobal.prisma.todo_users.findFirst({
    where: { email: props.body.email },
  });
  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 2. Validate the password
  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 3. Prepare immutable, type-safe date strings
  const now = toISOStringSafe(new Date());
  const accessExpiredAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiredAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // 4. Create a new session
  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: v4(),
      todo_user_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpiredAt,
    },
  });

  // 5. Issue JWT access and refresh tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiredAt,
    refreshable_until: refreshExpiredAt,
  };

  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoUser.ICreate;
}): Promise<ITodoUser.IAuthorized> {
  // 1. Email uniqueness check
  const existing = await MyGlobal.prisma.todo_users.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // 2. Password hashing
  const password_hash = await PasswordUtil.hash(props.body.password);

  // 3. User record creation
  const userId = v4();
  const now = toISOStringSafe(new Date());
  const user = await MyGlobal.prisma.todo_users.create({
    data: {
      id: userId,
      email: props.body.email,
      password_hash,
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Session creation
  const sessionId = v4();
  let sessionData: any = {
    id: sessionId,
    todo_user_id: user.id,
    href: props.body.href,
    referrer: props.body.referrer,
    created_at: now,
    expired_at: null,
  };
  if (props.body.ip !== undefined && props.body.ip !== null) {
    sessionData.ip = props.body.ip satisfies string as string;
  }
  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: sessionData,
  });

  // 5. JWT token generation
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const token = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // 6. Return authorized user DTO
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

